<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import type {ProjectionEntry,ProjectionFormat,ProjectionAnalysis,ProjectionChoices} from '@shared/projections'
import SelectMenu from './SelectMenu.vue'
import {errText} from '../api'
import {toast} from '../store'
const props=defineProps<{entry:ProjectionEntry}>(),emit=defineEmits<{close:[];done:[]}>()
const format=ref<ProjectionFormat>(props.entry.kind),version=ref(''),versions=ref<{version:string;supported:boolean}[]>([]),analysis=ref<ProjectionAnalysis>(),choices=ref<ProjectionChoices>({}),busy=ref(false),error=ref(''),output=ref('')
let generation=0,disposed=false
const ready=computed(()=>!!analysis.value&&!analysis.value.unsupported&&analysis.value.differences.every(d=>!!choices.value[d.key]))
function invalidate(){generation++;if(analysis.value)void window.kamucl.invoke('projections:discardAnalysis',analysis.value.id);analysis.value=undefined;choices.value={};error.value='';output.value=''}
watch([format,version],invalidate)
async function analyze(){if(busy.value)return;invalidate();const request=++generation;busy.value=true;try{const next=await window.kamucl.invoke('projections:analyze',props.entry.id,format.value,version.value||undefined) as ProjectionAnalysis;if(disposed||request!==generation){void window.kamucl.invoke('projections:discardAnalysis',next.id);return}analysis.value=next}catch(e){if(!disposed&&request===generation)error.value=errText(e)}finally{if(!disposed)busy.value=false}}
async function convert(){if(!ready.value||busy.value)return;busy.value=true;error.value='';try{const result=await window.kamucl.invoke('projections:convert',analysis.value!.id,JSON.parse(JSON.stringify(choices.value))) as {path:string;name:string};output.value=result.path;analysis.value=undefined;emit('done');toast('投影副本已生成并重新读取验证','success')}catch(e){error.value=errText(e)}finally{busy.value=false}}
onMounted(async()=>{try{versions.value=await window.kamucl.invoke('projections:versions') as typeof versions.value}catch(e){error.value=errText(e)}})
onUnmounted(()=>{disposed=true;invalidate()})
</script>
<template><Teleport to="body"><div class="modal-mask" @keydown.esc="!busy&&emit('close')"><section class="modal conversion" role="dialog" aria-modal="true" aria-label="投影转换"><header><h2>转换投影</h2><button class="btn btn-ghost" :disabled="busy" aria-label="关闭转换" @click="emit('close')">×</button></header><p class="muted">{{entry.name}} · 原文件保留，重名生成独立副本</p><div class="targets"><label>目标格式<SelectMenu v-model="format" :disabled="busy" :options="['litematic','schem','schematic','nbt'].map(v=>({value:v,label:'.'+v}))"/></label><label>目标游戏版本<SelectMenu v-model="version" :disabled="busy" :options="[{value:'',label:'保留原游戏版本（仅格式转换）'},...versions.map(v=>({value:v.version,label:v.version+(v.supported?'':' · 暂不支持')}))]"/></label></div><button class="btn btn-gold" :disabled="busy" @click="analyze">{{busy?'后台任务处理中…':'分析差异'}}</button><p class="muted">进度和取消可在任务中心操作。</p><p v-if="error" class="failed" role="alert">{{error}}</p><template v-if="analysis"><p v-if="analysis.unsupported" class="failed" role="alert">{{analysis.unsupported}}</p><template v-else><p>共 {{analysis.blocks}} 个方块 · {{analysis.differences.length}} 项差异</p><div v-for="d in analysis.differences" :key="d.key" class="difference"><strong>{{d.description}}</strong><span class="muted">数量 {{d.count}}</span><label v-if="d.discardOnly"><input type="checkbox" :checked="choices[d.key]==='discard'" @change="choices[d.key]=($event.target as HTMLInputElement).checked?'discard':''">确认舍弃此数据</label><template v-else><SelectMenu :model-value="choices[d.key]==='discard'?'discard':choices[d.key]?'replace':''" :options="[{value:'',label:'请选择处理方式'},{value:'discard',label:'舍弃并替换为空气'},{value:'replace',label:'手动指定替代方块状态'}]" @update:model-value="choices[d.key]=$event==='replace'?(d.replacement||'minecraft:air'):$event"/><input v-if="choices[d.key]&&choices[d.key]!=='discard'" v-model="choices[d.key]" class="input" aria-label="替代方块状态" placeholder="minecraft:oak_log[axis=y]"></template></div><button class="btn btn-gold" :disabled="!ready||busy" @click="convert">确认生成并验证新文件</button></template></template><p v-if="output" role="status" class="output">已生成：{{output}}<br>关闭后可选择新文件并分发到实例。</p></section></div></Teleport></template>
<style scoped>.conversion{width:min(760px,92vw);max-height:90vh;overflow:auto;padding:24px}.conversion header{display:flex;justify-content:space-between;align-items:center}.conversion h2{margin:0}.targets{display:grid;grid-template-columns:1fr 1.5fr;gap:16px;margin:16px 0}.targets label{display:grid;gap:8px}.difference{display:grid;gap:8px;border-bottom:1px solid var(--border);padding:14px 0;overflow-wrap:anywhere}.conversion>.btn{margin-top:16px}.failed{color:var(--danger,#e05260)}.output{overflow-wrap:anywhere;line-height:1.7}@media(max-width:650px){.targets{grid-template-columns:1fr}}</style>
